// requiredTmdb is the Deps.RequiredSecrets closure standing in for a plugin
// handshake that declares ONE required secret for tmdb (tmdb-enrichment D2):
// every other plugin's declared set is empty.
func requiredTmdb(pluginID string) []string {
	if pluginID == "tmdb" {
		return []string{"api_key"}
	}
	return nil
}

// TestDerivationSkipsUnconfiguredServerBinding pins design D3's derivation
// half: a SERVER binding whose Options JSON lacks a declared required secret
// derives NO work (no ledger row, no retry churn — dormant), while the SAME
// binding with the secret resolved derives normally and the nil
// Deps.RequiredSecrets default keeps every existing source byte-identical.
// The registry's seeded tv module binds tmdb SERVER with options lacking
// api_key, so the unconfigured shape is the stock state.
func TestDerivationSkipsUnconfiguredServerBinding(t *testing.T) {
	ctx := context.Background()

	seed := func(t *testing.T) (*store.Store, *module.Registry, int64) {
		t.Helper()
		s, reg := queueTestStore(t)
		libID, err := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		if err != nil {
			t.Fatalf("CreateLibrary: %v", err)
		}
		doc := baseDoc("Show/S01E01.mkv")
		doc["sources"] = map[string]any{"tv-parser": map[string]any{"title": "parsed"}}
		putItem(t, s, "i_unconf", libID, statusEnriched, doc)
		return s, reg, libID
	}

	t.Run("unconfigured_binding_derives_nothing", func(t *testing.T) {
		s, reg, libID := seed(t)
		q := NewQueue(Deps{Store: s, Modules: reg, RequiredSecrets: requiredTmdb}, QueueConfig{})
		tasks, err := q.deriveLibrary(ctx, libID)
		if err != nil {
			t.Fatalf("deriveLibrary: %v", err)
		}
		if got := pluginIDs(tasks); got["tmdb"] {
			t.Fatalf("unconfigured tmdb derived %v, want dormant (no task)", got)
		}
	})

	t.Run("resolved_binding_derives_normally", func(t *testing.T) {
		s, reg, libID := seed(t)
		if err := reg.SetBindingOptions(ctx, "tv", "tmdb", json.RawMessage(`{"api_key":"k","language":"en-US"}`)); err != nil {
			t.Fatalf("SetBindingOptions: %v", err)
		}
		q := NewQueue(Deps{Store: s, Modules: reg, RequiredSecrets: requiredTmdb}, QueueConfig{})
		tasks, err := q.deriveLibrary(ctx, libID)
		if err != nil {
			t.Fatalf("deriveLibrary: %v", err)
		}
		if got := pluginIDs(tasks); !got["tmdb"] {
			t.Fatalf("resolved tmdb derived %v, want a task", got)
		}
	})

	t.Run("nil_deps_default_derives_byte_identically", func(t *testing.T) {
		s, reg, libID := seed(t)
		q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{})
		tasks, err := q.deriveLibrary(ctx, libID)
		if err != nil {
			t.Fatalf("deriveLibrary: %v", err)
		}
		if got := pluginIDs(tasks); !got["tmdb"] {
			t.Fatalf("nil RequiredSecrets default derived %v, want tmdb queued (today's behavior)", got)
		}
	})
}

// TestSearchSourceUnconfiguredSentinel pins design D3's interactive search
// half: an unconfigured SERVER source answers the typed ErrUnconfiguredSource
// BEFORE SearchSpecs executes (the scripted SearchSpecs error would surface
// its own sentinel if the pre-check were skipped), and the SAME source with
// its secret resolved executes the search end to end.
func TestSearchSourceUnconfiguredSentinel(t *testing.T) {
	ctx := context.Background()
	live := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		_, _ = w.Write([]byte(`[]`))
	}))
	t.Cleanup(live.Close)

	s, reg := queueTestStore(t)
	// SearchSpecs is scripted to answer the unsupported sentinel: if the
	// pre-check were skipped, the answer would carry ITS text, not ours.
	src := &searchSrc{specErr: sdk.ErrSearchUnsupported}
	q := NewQueue(Deps{Store: s, Modules: reg, RequiredSecrets: requiredTmdb}, QueueConfig{})
	q.resolve = mapResolver{"tmdb": src}.resolver()

	_, err := q.SearchSource(ctx, "tmdb", "aria", "")
	if !errors.Is(err, ErrUnconfiguredSource) {
		t.Fatalf("err = %v, want ErrUnconfiguredSource", err)
	}
	if errors.Is(err, sdk.ErrSearchUnsupported) {
		t.Fatalf("SearchSpecs executed past the D3 pre-check (err carries its sentinel): %v", err)
	}

	// The configured twin: the same closure passes the same pre-check and the
	// search runs the full fetch path against the live stub.
	if err := reg.SetBindingOptions(ctx, "tv", "tmdb", json.RawMessage(`{"api_key":"k"}`)); err != nil {
		t.Fatalf("SetBindingOptions: %v", err)
	}
	searching := &searchSrc{spec: &metadatav1.RequestSpec{Method: "GET", UrlTemplate: live.URL + "/search"}}
	q.resolve = mapResolver{"tmdb": searching}.resolver()
	cands, err := q.SearchSource(ctx, "tmdb", "aria", "")
	if err != nil {
		t.Fatalf("SearchSource (configured): %v", err)
	}
	if len(cands) != 0 {
		t.Fatalf("candidates = %v, want the empty page", cands)
	}
}

// TestIdentifySeriesUnconfiguredWritesNothing pins design D3's identify law:
// an unconfigured source's identify answers ErrUnconfiguredSource BEFORE any
// write — before the lease, the anchor write, the strip, the notify — so the
// row's document stays byte-identical and no anchor exists that the dormant
// source could never re-derive.
func TestIdentifySeriesUnconfiguredWritesNothing(t *testing.T) {
	ctx := context.Background()
	s, reg := queueTestStore(t)
	libID, err := s.CreateLibrary(ctx, "serial", filepath.Join(t.TempDir(), "lib"), "TV")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	doc := serialDoc("Show.Name.S01")
	doc["sources"] = map[string]any{
		"serial-parser": map[string]any{"title": "Show Name", "season": int64(1)},
	}
	serID := putSeriesRow(t, s, "serial", libID, "Show.Name.S01", statusReady, doc)
	before, err := s.GetSeries(ctx, serID, access.System())
	if err != nil {
		t.Fatalf("GetSeries: %v", err)
	}

	q := NewQueue(Deps{Store: s, Modules: reg, RequiredSecrets: requiredTmdb}, QueueConfig{})
	queued, stripped, deferred, err := q.IdentifySeries(ctx, serID, "tmdb", "12345")
	if !errors.Is(err, ErrUnconfiguredSource) {
		t.Fatalf("err = %v, want ErrUnconfiguredSource", err)
	}
	if queued || stripped != 0 || deferred != 0 {
		t.Fatalf("queued=%v stripped=%d deferred=%d, want false/0/0 (nothing done)", queued, stripped, deferred)
	}
	after, err := s.GetSeries(ctx, serID, access.System())
	if err != nil {
		t.Fatalf("GetSeries after: %v", err)
	}
	if string(before.Document) != string(after.Document) {
		t.Fatalf("an unconfigured identify must write nothing:\nbefore %s\nafter  %s", before.Document, after.Document)
	}
}
